//! Zeig's bridge to [rars](https://github.com/bitplane/rars), an independent, Apache-2.0
//! implementation of the RAR format in Rust.
//!
//! Everything marked `#[uniffi::export]` (functions) or `#[derive(uniffi::…)]` (types)
//! appears in Swift, generated by UniFFI into `ZeigRars.swift`:
//!
//! | Rust                         | Swift                                  |
//! |------------------------------|----------------------------------------|
//! | `fn create_archive(…)`       | `func createArchive(…) throws(RarError)` |
//! | `struct RarPackOptions`      | `struct RarPackOptions` (memberwise init) |
//! | `enum RarVersion`            | `enum RarVersion`                      |
//! | `enum RarError`              | `enum RarError: Error`                 |
//! | `trait RarProgress` (foreign)| `protocol RarProgress` Swift implements |
//!
//! The functions are blocking; Swift calls them from a background task. Strings are UTF-8
//! paths. Nothing here keeps state between calls.
//!
//! Zeig uses rars as an *experimental* backend (see the README): it is off by default and
//! every archive it writes is checked by 7-Zip afterwards.

use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use rars::version::ArchiveVersion;
use rars::{ArchiveReadOptions, ArchiveReader, Builder, ErrorKind, ReadCancellation};

uniffi::setup_scaffolding!();

// MARK: - Types shared with Swift

/// The RAR format version to write.
#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum RarVersion {
    /// RAR 2.9 ("RAR4" archives), readable by every RAR tool since 2000.
    Rar29,
    /// RAR 5 archives (WinRAR 5.0 and later).
    Rar50,
    /// RAR 7: the RAR 5 container with RAR 7's larger dictionaries.
    Rar70,
}

impl From<RarVersion> for ArchiveVersion {
    fn from(version: RarVersion) -> Self {
        match version {
            RarVersion::Rar29 => ArchiveVersion::Rar29,
            RarVersion::Rar50 => ArchiveVersion::Rar50,
            RarVersion::Rar70 => ArchiveVersion::Rar70,
        }
    }
}

/// How to write a new archive. Swift gets a memberwise initializer with these defaults.
#[derive(Debug, Clone, uniffi::Record)]
pub struct RarPackOptions {
    pub version: RarVersion,
    /// 0 (store, no compression) … 5 (best). `None` uses rars' default.
    #[uniffi(default = None)]
    pub level: Option<u8>,
    /// Compress all files as one stream: smaller, but one damaged byte affects everything after it.
    #[uniffi(default = false)]
    pub solid: bool,
    #[uniffi(default = None)]
    pub password: Option<String>,
    /// Also encrypt the file names (needs a password).
    #[uniffi(default = false)]
    pub encrypt_headers: bool,
    /// Recovery record size in percent of the archive (1–100), for repairing damage later.
    #[uniffi(default = None)]
    pub recovery_percent: Option<u64>,
    /// Split into volumes of this many bytes (RAR 5/7 only), named name.part1.rar, ….
    #[uniffi(default = None)]
    pub volume_size: Option<u64>,
    #[uniffi(default = None)]
    pub comment: Option<String>,
}

/// One file or folder in an archive.
#[derive(Debug, Clone, uniffi::Record)]
pub struct RarEntry {
    /// Path inside the archive with '/' separators.
    pub path: String,
    pub size: u64,
    pub packed_size: u64,
    /// Seconds since 1970, if stored.
    pub modified: Option<i64>,
    pub is_directory: bool,
    pub is_encrypted: bool,
}

/// Why an operation failed. `message` is English detail from rars, for logs and bug reports.
#[derive(Debug, thiserror::Error, uniffi::Error)]
pub enum RarError {
    #[error("the archive needs a password")]
    PasswordRequired,
    #[error("the password is wrong")]
    WrongPassword,
    #[error("the archive is damaged: {message}")]
    Corrupt { message: String },
    #[error("not supported by rars: {message}")]
    Unsupported { message: String },
    #[error("file error: {message}")]
    Io { message: String },
    #[error("cancelled")]
    Cancelled,
    #[error("invalid option: {message}")]
    InvalidOption { message: String },
    #[error("rars failed: {message}")]
    Other { message: String },
}

impl From<rars::Error> for RarError {
    fn from(error: rars::Error) -> Self {
        let message = error.to_string();
        match error.kind() {
            ErrorKind::PasswordRequired => RarError::PasswordRequired,
            ErrorKind::BadPassword => RarError::WrongPassword,
            ErrorKind::InvalidArchive | ErrorKind::ChecksumMismatch | ErrorKind::UnsafePath => {
                RarError::Corrupt { message }
            }
            ErrorKind::UnsupportedFormat | ErrorKind::UnsupportedFeature => {
                RarError::Unsupported { message }
            }
            ErrorKind::Io | ErrorKind::SourceChanged => RarError::Io { message },
            ErrorKind::Cancelled => RarError::Cancelled,
            ErrorKind::InvalidArgument | ErrorKind::ResourceLimit => {
                RarError::InvalidOption { message }
            }
            _ => RarError::Other { message },
        }
    }
}

impl From<std::io::Error> for RarError {
    fn from(error: std::io::Error) -> Self {
        RarError::Io { message: error.to_string() }
    }
}

/// Progress reports, implemented in Swift. Return `false` to cancel.
#[uniffi::export(with_foreign)]
pub trait RarProgress: Send + Sync {
    fn report(&self, completed: u64, total: u64) -> bool;
}

// MARK: - Functions

/// The rars version Zeig was built with, such as "0.12.3".
#[uniffi::export]
pub fn rars_version() -> String {
    // Kept in step with the exact pin in Cargo.toml.
    "0.12.3".to_string()
}

/// Writes a new archive at `destination` from `sources` (files or folders, added
/// recursively and named relative to their parent folder). Returns the paths written: one,
/// or every volume of a split archive. Symbolic links in the sources are refused.
#[uniffi::export]
pub fn create_archive(
    destination: String,
    sources: Vec<String>,
    options: RarPackOptions,
    progress: Option<Arc<dyn RarProgress>>,
) -> Result<Vec<String>, RarError> {
    if sources.is_empty() {
        return Err(RarError::InvalidOption { message: "nothing to add".into() });
    }
    if options.encrypt_headers && options.password.is_none() {
        return Err(RarError::InvalidOption {
            message: "encrypting file names needs a password".into(),
        });
    }

    let mut builder = Builder::new(options.version.into())
        .compression_level(options.level)
        .store(options.level == Some(0))
        .solid(options.solid)
        .password(options.password.map(String::into_bytes))
        .header_encryption(options.encrypt_headers)
        .recovery_percent(options.recovery_percent)
        .comment(options.comment.map(String::into_bytes));
    let family_is_rar5 = !matches!(options.version, RarVersion::Rar29);
    for source in &sources {
        let path = Path::new(source);
        let name = path
            .file_name()
            .ok_or_else(|| RarError::InvalidOption { message: format!("no file name in {source}") })?;
        // rars' add_path adds the files under a folder but not the folders themselves, so
        // an empty folder would vanish. Add every folder explicitly first.
        add_directories(&mut builder, path, name.as_encoded_bytes(), family_is_rar5)?;
        builder.add_path(path, name.as_encoded_bytes())?;
    }

    let relay = progress.map(|callback| ProgressRelay { callback, cancelled: Default::default() });
    let reporter = relay.as_ref().map(|r| r as &dyn rars::WriteProgress);
    let destination = PathBuf::from(destination);
    match options.volume_size {
        None => {
            builder.write_to_path(&destination, reporter)?;
            Ok(vec![destination.to_string_lossy().into_owned()])
        }
        Some(size) => {
            let builder = builder.volume_size(Some(usize::try_from(size).unwrap_or(usize::MAX)));
            write_volumes(&builder, &destination, reporter)
        }
    }
}

/// Adds `path` (named `name`) and every folder below it as directory entries, named the way
/// `Builder::add_path` names files (RAR 5/7 wire names are re-encoded on Unix).
fn add_directories(builder: &mut Builder, path: &Path, name: &[u8], rar5: bool) -> Result<(), RarError> {
    let meta = fs::symlink_metadata(path)?;
    if !meta.is_dir() {
        return Ok(());
    }
    let wire_name = if rar5 { rars::filename::encode_rar50(name).into_owned() } else { name.to_vec() };
    use std::os::unix::fs::PermissionsExt;
    builder.add_directory(wire_name, None, Some(meta.permissions().mode()))?;
    let mut children = fs::read_dir(path)?.collect::<Result<Vec<_>, _>>()?;
    children.sort_by_key(|entry| entry.file_name());
    for child in children {
        let mut child_name = name.to_vec();
        child_name.push(b'/');
        child_name.extend_from_slice(child.file_name().as_encoded_bytes());
        add_directories(builder, &child.path(), &child_name, rar5)?;
    }
    Ok(())
}

/// Lists the entries of the archive at `path` (the first volume for a split archive; the
/// other volumes are read too, so files spanning them are listed once).
#[uniffi::export]
pub fn list_entries(path: String, password: Option<String>) -> Result<Vec<RarEntry>, RarError> {
    let password = password.map(String::into_bytes);
    let volumes = volume_paths(Path::new(&path))
        .iter()
        .map(|volume| {
            ArchiveReader::read_path_with_options(
                volume,
                ArchiveReadOptions::with_optional_password(password.as_deref()),
            )
        })
        .collect::<rars::Result<Vec<_>>>()?;
    let members = if volumes.len() > 1 {
        rars::volume_members(&volumes)?
    } else {
        volumes[0].members().collect()
    };
    let mut entries = Vec::new();
    for member in members {
        let name = member.decoded_name(None)?;
        entries.push(RarEntry {
            path: String::from_utf8_lossy(&name).replace('\\', "/"),
            size: member.meta.unpacked_size,
            packed_size: member.meta.packed_size,
            modified: member
                .meta
                .modification_time()
                .and_then(|time| time.duration_since(std::time::UNIX_EPOCH).ok())
                .map(|duration| duration.as_secs() as i64),
            is_directory: member.meta.is_directory,
            is_encrypted: member.meta.is_encrypted,
        });
    }
    Ok(entries)
}

/// Extracts everything into the existing folder `destination`. Paths that would leave the
/// folder are refused (the whole extraction fails as Corrupt); links are skipped.
#[uniffi::export]
pub fn extract_archive(
    path: String,
    destination: String,
    password: Option<String>,
    progress: Option<Arc<dyn RarProgress>>,
) -> Result<(), RarError> {
    run_extraction(&path, Some(Path::new(&destination)), password, progress)
}

/// Decompresses everything and checks the checksums without writing files.
#[uniffi::export]
pub fn test_archive(path: String, password: Option<String>) -> Result<(), RarError> {
    run_extraction(&path, None, password, None)
}

// MARK: - Extraction

fn run_extraction(
    path: &str,
    destination: Option<&Path>,
    password: Option<String>,
    progress: Option<Arc<dyn RarProgress>>,
) -> Result<(), RarError> {
    let password = password.map(String::into_bytes);
    let cancellation = ReadCancellation::new();
    let options = || {
        ArchiveReadOptions::with_optional_password(password.as_deref()).with_cancellation(&cancellation)
    };
    let volumes = volume_paths(Path::new(path))
        .iter()
        .map(|volume| ArchiveReader::read_path_with_options(volume, options()))
        .collect::<rars::Result<Vec<_>>>()?;

    let total: u64 = rars::volume_members(&volumes)
        .map(|members| members.iter().map(|m| m.meta.unpacked_size).sum())
        .unwrap_or(0);
    let counter = Arc::new(ByteCounter { done: Default::default(), total, progress, cancellation: cancellation.child() });

    let open = |meta: &rars::ExtractedEntryMeta| -> rars::Result<Box<dyn Write>> {
        let sink: Box<dyn Write> = match destination {
            None => Box::new(std::io::sink()),
            Some(root) => {
                let name = rars::filename::decoded_name(&meta.name, meta.name_is_unicode, None)?;
                let target = root.join(rars::entry_relative_path(&name)?);
                if meta.is_directory {
                    fs::create_dir_all(&target)?;
                    Box::new(std::io::sink())
                } else {
                    if let Some(parent) = target.parent() {
                        fs::create_dir_all(parent)?;
                    }
                    // Replace, never write through, whatever is there (it might be a link).
                    let _ = fs::remove_file(&target);
                    Box::new(fs::File::create(&target)?)
                }
            }
        };
        Ok(Box::new(CountingWriter { inner: sink, counter: counter.clone() }))
    };
    let skip_links = |_: &rars::ExtractedEntryMeta, _: rars::ExtractedLink<'_>| Ok(());

    let result = if volumes.len() > 1 {
        rars::extract_volumes_with_links(&volumes, options(), open, skip_links)
    } else {
        volumes[0].extract_with_links(options(), open, skip_links)
    };
    if cancellation.is_cancelled() {
        return Err(RarError::Cancelled);
    }
    result.map_err(RarError::from)
}

/// `name.part1.rar` → every `name.partN.rar` that exists, in order. Anything else → itself.
/// (Old-style `name.rar`, `name.r00`, … sets are found by rars from the first volume.)
fn volume_paths(first: &Path) -> Vec<PathBuf> {
    let file_name = first.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_default();
    let lower = file_name.to_lowercase();
    let Some(stem_end) = lower.rfind(".part") else { return vec![first.to_path_buf()] };
    let digits = &lower[stem_end + 5..];
    let Some(number) = digits.strip_suffix(".rar") else { return vec![first.to_path_buf()] };
    if number.is_empty() || !number.bytes().all(|b| b.is_ascii_digit()) {
        return vec![first.to_path_buf()];
    }
    let width = number.len();
    let stem = &file_name[..stem_end];
    let mut paths = Vec::new();
    for index in 1.. {
        let candidate = first.with_file_name(format!("{stem}.part{index:0width$}.rar"));
        if !candidate.exists() {
            break;
        }
        paths.push(candidate);
    }
    if paths.is_empty() {
        paths.push(first.to_path_buf());
    }
    paths
}

/// Counts bytes written by extraction, reports them, and turns a `false` from Swift into
/// rars' cooperative cancellation.
struct ByteCounter {
    done: std::sync::atomic::AtomicU64,
    total: u64,
    progress: Option<Arc<dyn RarProgress>>,
    cancellation: ReadCancellation,
}

struct CountingWriter {
    inner: Box<dyn Write>,
    counter: Arc<ByteCounter>,
}

impl Write for CountingWriter {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        let written = self.inner.write(buf)?;
        let counter = &self.counter;
        let done = counter.done.fetch_add(written as u64, std::sync::atomic::Ordering::Relaxed) + written as u64;
        if let Some(progress) = &counter.progress {
            if !progress.report(done, counter.total) {
                counter.cancellation.cancel();
                return Err(std::io::Error::other("cancelled"));
            }
        }
        Ok(written)
    }

    fn flush(&mut self) -> std::io::Result<()> {
        self.inner.flush()
    }
}

// MARK: - Writing

struct ProgressRelay {
    callback: Arc<dyn RarProgress>,
    cancelled: std::sync::atomic::AtomicBool,
}

impl rars::WriteProgress for ProgressRelay {
    fn report(&self, event: rars::WriteProgressEvent<'_>) {
        if let rars::WriteProgressEvent::Advanced { completed_bytes, total_bytes, .. } = event {
            if !self.callback.report(completed_bytes, total_bytes) {
                self.cancelled.store(true, std::sync::atomic::Ordering::Relaxed);
            }
        }
    }

    fn is_cancelled(&self) -> bool {
        self.cancelled.load(std::sync::atomic::Ordering::Relaxed)
    }
}

/// Writes a volume set as `name.partN.rar`, numbered with as many digits as the count needs
/// (part1…part9, or part01…part12), like WinRAR. Volumes are written to temporary names first
/// and renamed at the end, so a failure leaves nothing behind.
fn write_volumes(
    builder: &Builder,
    destination: &Path,
    progress: Option<&dyn rars::WriteProgress>,
) -> Result<Vec<String>, RarError> {
    struct Sink<'a> {
        destination: &'a Path,
        temporaries: Vec<PathBuf>,
    }
    impl rars::rar50::VolumeSink for Sink<'_> {
        fn start_volume(&mut self, index: u64) -> rars::Result<Box<dyn Write + Send>> {
            let temporary = self.destination.with_file_name(format!(".zeig-volume-{index}.tmp"));
            let file = fs::File::create(&temporary)?;
            self.temporaries.push(temporary);
            Ok(Box::new(file))
        }
    }

    let mut sink = Sink { destination, temporaries: Vec::new() };
    let resources = rars::WriterResources::default()
        .with_temp_dir(destination.parent().unwrap_or(Path::new(".")));
    let result = builder.write_volumes_to(&mut sink, &resources, progress);
    if let Err(error) = result {
        for temporary in &sink.temporaries {
            let _ = fs::remove_file(temporary);
        }
        return Err(error.into());
    }

    let count = sink.temporaries.len();
    let width = count.to_string().len();
    let stem = destination
        .file_stem()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| "archive".into());
    let mut written = Vec::new();
    for (index, temporary) in sink.temporaries.iter().enumerate() {
        let name = format!("{stem}.part{:0width$}.rar", index + 1);
        let final_path = destination.with_file_name(name);
        fs::rename(temporary, &final_path)?;
        written.push(final_path.to_string_lossy().into_owned());
    }
    Ok(written)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn single_archives_are_their_own_volume() {
        let path = Path::new("/nowhere/photos.rar");
        assert_eq!(volume_paths(path), vec![path.to_path_buf()]);
    }

    #[test]
    fn volume_sets_are_found_in_order() {
        let dir = std::env::temp_dir().join(format!("zeig-rars-test-{}", std::process::id()));
        fs::create_dir_all(&dir).unwrap();
        for part in ["set.part01.rar", "set.part02.rar", "set.part03.rar"] {
            fs::write(dir.join(part), b"").unwrap();
        }
        let found = volume_paths(&dir.join("set.part01.rar"));
        let names: Vec<_> = found.iter().map(|p| p.file_name().unwrap().to_string_lossy().into_owned()).collect();
        assert_eq!(names, ["set.part01.rar", "set.part02.rar", "set.part03.rar"]);
        fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn round_trip_through_the_exported_functions() {
        let dir = std::env::temp_dir().join(format!("zeig-rars-rt-{}", std::process::id()));
        let source = dir.join("input");
        fs::create_dir_all(source.join("empty")).unwrap();
        fs::write(source.join("hello.txt"), b"hello").unwrap();
        let archive = dir.join("out.rar");
        let options = RarPackOptions {
            version: RarVersion::Rar70,
            level: Some(3),
            solid: false,
            password: Some("pw".into()),
            encrypt_headers: true,
            recovery_percent: None,
            volume_size: None,
            comment: None,
        };
        create_archive(archive.to_string_lossy().into(), vec![source.to_string_lossy().into()], options, None).unwrap();

        assert!(matches!(list_entries(archive.to_string_lossy().into(), None), Err(RarError::PasswordRequired)));
        let entries = list_entries(archive.to_string_lossy().into(), Some("pw".into())).unwrap();
        assert!(entries.iter().any(|e| e.path == "input/hello.txt"));
        assert!(entries.iter().any(|e| e.path == "input/empty" && e.is_directory));

        let out = dir.join("out");
        fs::create_dir_all(&out).unwrap();
        extract_archive(archive.to_string_lossy().into(), out.to_string_lossy().into(), Some("pw".into()), None).unwrap();
        assert_eq!(fs::read(out.join("input/hello.txt")).unwrap(), b"hello");
        fs::remove_dir_all(&dir).unwrap();
    }
}
